def wrap_deg(angle):
    return (angle + 180) % 360 - 180

def clamp(value, low=-100, high=100):
    return max(low, min(high, value))

def wheel_commands(target_ccw, measured_ccw, base=30, kp=0.5):
    error = wrap_deg(target_ccw - measured_ccw)
    correction = kp * error
    return clamp(base - correction), clamp(base + correction)

print(wheel_commands(0, -10))  # (25.0, 35.0)
print(wrap_deg(179 - (-179)))  # -2

