# Both routes start at (0, 0, east). The goal checks position only.
WIDTH, HEIGHT = 5, 4
START = (0, 0, 0)
GOAL = (3, 2)
DIRECTIONS = [(1, 0), (0, 1), (-1, 0), (0, -1)]
ROUTES = {"A": "F R F L F F R F", "B": "F F F F R F F R F"}

def evaluate(commands, forward_s, turn_s):
    x, y, heading = START
    moves = turns = 0
    for command in commands.split():
        if command == "F":
            dx, dy = DIRECTIONS[heading]
            x, y = x + dx, y + dy
            moves += 1
            if not (0 <= x < WIDTH and 0 <= y < HEIGHT):
                return False, moves, turns, None
        elif command in ("L", "R"):
            heading = (heading + (1 if command == "R" else -1)) % 4
            turns += 1
        else:
            raise ValueError("Unknown command")
    success = (x, y) == GOAL
    return success, moves, turns, moves * forward_s + turns * turn_s

for forward_s, turn_s in [(1.0, 3.0), (2.0, 0.2)]:
    print("Model seconds per forward/turn:", forward_s, turn_s)
    candidates = []
    for name, route in ROUTES.items():
        success, moves, turns, cost = evaluate(route, forward_s, turn_s)
        print(name, "success:", success, "forward:", moves,
              "turns:", turns, "model seconds:", cost)
        if success:
            candidates.append((cost, name))
    print("Lowest-cost successful route:", min(candidates)[1] if candidates else None)

WIDTH, HEIGHT = 5, 4
BLOCKED = {(1, 1), (2, 1)}
START, GOAL = (0, 0), (3, 2)

def bfs(start, goal, blocked, width, height):
    def valid(cell):
        x, y = cell
        return 0 <= x < width and 0 <= y < height and cell not in blocked

    if not valid(start) or not valid(goal):
        return None
    queue = [start]
    head = 0
    parent = {start: None}
    while head < len(queue):
        current = queue[head]
        head += 1
        if current == goal:
            path = []
            while current is not None:
                path.append(current)
                current = parent[current]
            return path[::-1]
        x, y = current
        for neighbor in [(x + 1, y), (x, y + 1), (x - 1, y), (x, y - 1)]:
            if valid(neighbor) and neighbor not in parent:
                parent[neighbor] = current
                queue.append(neighbor)
    return None

path = bfs(START, GOAL, BLOCKED, WIDTH, HEIGHT)
print("Path:", path)
print("Forward steps:", len(path) - 1 if path is not None else None)
